<script lang="ts">
import {onMount} from 'svelte';
import {invoke} from '@tauri-apps/api/core';
import {listen} from '@tauri-apps/api/event';
import FolderOpen from 'lucide-svelte/icons/folder-open';
import Keyboard from 'lucide-svelte/icons/keyboard';
import Mic from 'lucide-svelte/icons/mic';
import Palette from 'lucide-svelte/icons/palette';
import Check from 'lucide-svelte/icons/check';
import Play from 'lucide-svelte/icons/play';
import RotateCcw from 'lucide-svelte/icons/rotate-ccw';
import NotebookPen from 'lucide-svelte/icons/notebook-pen';
import {updateSettings,type Settings,type VoiceState} from '$lib/api';
import MaterialPicker from '$lib/MaterialPicker.svelte';
import Tutorial from '$lib/Tutorial.svelte';
import DockDimensions from '$lib/DockDimensions.svelte';
import BookOpen from 'lucide-svelte/icons/book-open';
let cfg=$state<Settings|null>(null);let draft=$state<Settings|null>(null);let error=$state('');let message=$state('');let saving=$state(false);let tab=$state('general');let devices=$state<{name:string,is_default:boolean}[]>([]);let engine=$state('');let shortcutError=$state('');let dirty=$state(false);
let lexicon=$state('');
const modified=new Set<keyof Settings>();
function receive(next:Settings){
  const pending=draft?Object.fromEntries([...modified].map(key=>[key,draft![key]])):{};
  cfg=next;draft={...next,...pending};if(!modified.has('personal_words'))lexicon=(next.personal_words||[]).join('\n');
}
function engineText(voice:VoiceState){return voice.engine==='ready'?'Moteur prêt':voice.engine==='loading'?'Chargement du modèle…':voice.error||voice.message||'Moteur local'}
onMount(()=>{let alive=true;const off:(()=>void)[]=[];Promise.all([invoke<Settings>('settings_get'),invoke<{error:string|null}>('shortcuts_status'),invoke<VoiceState>('voice_get')]).then(([s,k,v])=>{receive(s);shortcutError=k.error||'';engine=engineText(v)}).catch(e=>error=String(e));invoke<typeof devices>('voice_devices').then(d=>devices=d).catch(()=>{});listen<string>('settings:navigate',e=>{if(e.payload==='layout')tab='layout'}).then(f=>alive?off.push(f):f());listen<Settings>('settings:changed',e=>receive(e.payload)).then(f=>alive?off.push(f):f());listen<VoiceState>('voice:state',e=>engine=engineText(e.payload)).then(f=>alive?off.push(f):f());listen<{error:string|null}>('shortcuts:status',e=>shortcutError=e.payload.error||'').then(f=>alive?off.push(f):f());return()=>{alive=false;off.forEach(f=>f())}});
function edit(event:Event){const name=(event.currentTarget as HTMLInputElement).name as keyof Settings;if(name)modified.add(name);dirty=modified.size>0;message='';error=''}
function distinctKeys(){if(!draft)return;draft.shortcut_dictation='Ctrl+Shift+Space';draft.shortcut_capture='Ctrl+Shift+S';modified.add('shortcut_dictation');modified.add('shortcut_capture');dirty=true;message='';error=''}
function onePressPreset(){if(!draft)return;draft.voice_mode='handsfree';modified.add('voice_mode');dirty=true;message='Un appui démarrera la dictée, un autre l’arrêtera. Enregistre pour appliquer.';error=''}
async function showSmallBase(reposition=false){error='';try{if(reposition)await invoke('dock_reset');await invoke('show_window',{label:'quick'});message='Petit socle affiché.'}catch(e){error=String(e)}}
async function save(){
  if(!draft)return;error='';message='';if(!modified.size)return;saving=true;
  try{const patch=Object.fromEntries([...modified].map(key=>[key,draft![key]]));const next=await updateSettings(patch);modified.clear();dirty=false;receive(next);message='Réglages enregistrés.'}
  catch(e){error=String(e)}finally{saving=false}
}
async function appearance(patch:Partial<Settings>){if(!draft||saving)return;saving=true;error='';try{receive(await updateSettings(patch))}catch(e){error=String(e)}finally{saving=false}}
function editLexicon(value:string){lexicon=value;if(draft)draft.personal_words=value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);modified.add('personal_words');dirty=true;message='';error=''}
async function choose(){try{const s=await invoke<Settings|null>('workspace_choose');if(s)receive(s)}catch(e){error=String(e)}}
async function retryKeys(){saving=true;error='';try{const result=await invoke<{error:string|null}>('shortcuts_retry');shortcutError=result.error||'';message=shortcutError?'':'Raccourcis actifs.'}catch(e){error=String(e)}finally{saving=false}}
function handsfreePreset(){if(!draft)return;draft.voice_mode='handsfree';draft.vad_silence_ms=3000;draft.large_controls=true;draft.reduce_motion=true;for(const key of ['voice_mode','vad_silence_ms','large_controls','reduce_motion'] as const)modified.add(key);dirty=true;message='Préréglage prêt : enregistre pour l’appliquer.';error=''}
async function preload(){await save();if(error)return;try{await invoke('voice_preload');engine='Préparation du moteur…'}catch(e){error=String(e)}}
</script>
<svelte:head><title>Écho V3 — Réglages</title></svelte:head>
<div class="settings-shell"><aside><div class="brand"><img src="/brand/echo-v3.png" alt="" width="30" height="30"/>écho <span>V3</span></div><h1>Réglages</h1><nav aria-label="Réglages"><button class:chosen={tab==='general'} onclick={()=>tab='general'}><FolderOpen size={17}/>Dossier et démarrage</button><button class:chosen={tab==='voice'} onclick={()=>tab='voice'}><Mic size={17}/>Voix et moteur</button><button class:chosen={tab==='keys'} onclick={()=>tab='keys'}><Keyboard size={17}/>Raccourcis</button><button class:chosen={tab==='layout'} onclick={()=>tab='layout'}><Keyboard size={17}/>Disposition des blocs</button><button class:chosen={tab==='appearance'} onclick={()=>tab='appearance'}><Palette size={17}/>Apparence</button><button class:chosen={tab==='access'} onclick={()=>tab='access'}><Keyboard size={17}/>Accessibilité</button><button class:chosen={tab==='tutorial'} onclick={()=>tab='tutorial'}><BookOpen size={17}/>Tutoriel</button></nav><div class="aside-bottom"><button class="btn ghost" onclick={()=>showSmallBase()}><Mic size={16}/>Afficher le petit socle</button><button class="btn ghost" onclick={()=>invoke('show_window',{label:'main'})}><NotebookPen size={16}/>Ouvrir les notes</button><p>Écho V3<br/>Notes, voix et captures.</p></div></aside>
<main>{#if draft}<fieldset disabled={saving}>
{#if tab==='general'}<h2>Un dossier pour tout retrouver</h2><p class="intro">Tes notes sont des fichiers Markdown. Les captures et les enregistrements sont rangés dans le même espace.</p><section><label class="label" for="workspace">Dossier actif</label><input id="workspace" class="field path" readonly value={draft.workspace}/><div class="actions"><button class="btn primary" onclick={choose}><FolderOpen size={16}/>Choisir un dossier</button><button class="btn" onclick={()=>invoke('workspace_open')}>Ouvrir dans l’Explorateur</button></div><dl><div><dt>Notes</dt><dd>Fichiers .md</dd></div><div><dt>Captures</dt><dd>captures</dd></div><div><dt>Enregistrements</dt><dd>.echo/audio</dd></div></dl></section><section><h3>Petit socle</h3><p class="hint">Tu l’as masqué ? Retrouve ici le micro et ses petits outils.</p><div class="actions"><button class="btn primary" onclick={()=>showSmallBase()}>Afficher le petit socle</button><button class="btn" onclick={()=>showSmallBase(true)}>Replacer en bas à droite</button></div></section><section><h3>Au quotidien</h3><label class="check"><input type="checkbox" name="always_on_top" bind:checked={draft.always_on_top} onchange={edit}/><span>Garder le socle et ses blocs au-dessus des autres fenêtres</span></label><label class="check"><input type="checkbox" name="autostart" bind:checked={draft.autostart} onchange={edit}/><span>Lancer Écho V3 avec Windows</span></label><p class="hint">Le microphone reste fermé au démarrage, y compris si tu utilises le mode mains libres.</p></section>
{:else if tab==='voice'}<h2>Une voix qui suit ton travail</h2><p class="intro">La transcription s’effectue sur ce PC. Place le curseur dans ton champ de texte : un clic sur le micro démarre l’écoute, un second l’arrête. Le texte provisoire apparaît pendant la parole ; le résultat final précis est recalculé à l’arrêt.</p><section class="grid"><label class="label">Microphone<select class="field" name="input_device" bind:value={draft.input_device} onchange={edit}><option value={null}>Microphone par défaut de Windows</option>{#each devices as d}<option value={d.name}>{d.name}</option>{/each}</select></label><label class="label">Geste du raccourci<select class="field" name="voice_mode" bind:value={draft.voice_mode} onchange={edit}><option value="hold">Maintenir pour parler</option><option value="toggle">Cliquer pour démarrer / arrêter</option><option value="handsfree">Mains libres, avec détection de parole</option></select></label><label class="label">Pause entre phrases (mains libres)<select class="field" name="vad_silence_ms" bind:value={draft.vad_silence_ms} onchange={edit}><option value={600}>Court · 0,6 s</option><option value={900}>Naturel · 0,9 s</option><option value={1400}>Posé · 1,4 s</option><option value={2000}>Long · 2 s</option><option value={3000}>Très posé · 3 s</option><option value={4500}>Avec des pauses · 4,5 s</option><option value={6000}>Prendre son temps · 6 s</option></select></label></section><section><label class="check"><input type="checkbox" name="keep_audio" bind:checked={draft.keep_audio} onchange={edit}/><span>Conserver aussi les fichiers audio des dictées réussies</span></label><p class="hint">Les enregistrements du dictaphone et l’audio nécessaire à un réessai sont conservés.</p></section><section><h3>Moteur local</h3><label class="label">Interpréteur Python<input class="field path" name="python" bind:value={draft.python} oninput={edit} spellcheck="false"/></label><div class="grid"><label class="label">Langue<select class="field" name="language" bind:value={draft.language} onchange={edit}><option value="fr">Français</option><option value="en">Anglais</option><option value="nl">Néerlandais</option><option value="de">Allemand</option><option value="auto">Détection automatique</option></select></label></div><div class="actions"><button class="btn" disabled={saving} onclick={preload}><Play size={15}/>Charger le moteur</button><span class="status" aria-live="polite">{engine}</span></div><p class="hint">La dictée fonctionne localement sur ce PC. Les mots reconnus dépendent de ta voix et du bruit. L’aperçu évolue pendant la parole ; le résultat final précis est recalculé quand tu arrêtes le micro.</p></section><section><h3>Ton vocabulaire</h3><label class="label" for="personal-words">Noms et expressions à reconnaître<textarea id="personal-words" class="field lexicon" rows="5" value={lexicon} oninput={e=>editLexicon(e.currentTarget.value)} placeholder="Écho&#10;Ouvrane&#10;Nom de ton entreprise"></textarea></label><p class="hint">Une expression par ligne, jusqu’à 64 expressions de 64 caractères. Elles guident la dictée et sont reconnues par le correcteur local. Les corrections restent à accepter volontairement.</p></section>
{:else if tab==='keys'}<h2>Les gestes à portée de main</h2><p class="intro">Les raccourcis fonctionnent aussi quand Écho est en arrière-plan.</p><section><label class="label">Dictée<input class="field shortcut" name="shortcut_dictation" bind:value={draft.shortcut_dictation} oninput={edit} spellcheck="false"/></label><p class="hint">Choisis une touche comme 1, A ou F8, ou une combinaison comme Ctrl+Alt+Space. Une touche seule démarre au premier appui et arrête au suivant ; elle est réservée à Écho tant que l’application est ouverte.</p><button class="btn" onclick={onePressPreset}>Un appui démarre / un autre arrête</button><label class="label">Capture d’écran<input class="field shortcut" name="shortcut_capture" bind:value={draft.shortcut_capture} oninput={edit} spellcheck="false"/></label><p class="hint">Écris une combinaison telle que Ctrl+Alt+Space ou Ctrl+Shift+F8.</p>{#if shortcutError}<div class="notice error">{shortcutError}</div><button class="btn" disabled={saving||dirty} onclick={retryKeys}><RotateCcw size={15}/>Réactiver les raccourcis</button>{/if}<button class="btn" onclick={distinctKeys}>Utiliser des raccourcis distincts de la V1</button></section><section><h3>Dans les outils</h3><dl><div><dt>Nouvelle note</dt><dd><kbd>Ctrl + N</kbd></dd></div><div><dt>Enregistrer</dt><dd><kbd>Ctrl + S</kbd></dd></div><div><dt>Rechercher dans la note</dt><dd><kbd>Ctrl + F</kbd></dd></div><div><dt>Fermer la capture en conservant le brouillon</dt><dd><kbd>Échap</kbd></dd></div></dl></section>
{:else if tab==='access'}<h2>Écho à ton rythme</h2><p class="intro">Dicter sans maintenir une touche et disposer de commandes plus faciles à atteindre. Le micro reste fermé tant que tu ne l’actives pas.</p><section><h3>Parler les mains libres</h3><p class="hint">Le préréglage active les mains libres, laisse trois secondes entre les phrases et agrandit les commandes des blocs. Tu peux choisir jusqu’à six secondes de pause dans « Voix et moteur ».</p><button class="btn primary" onclick={handsfreePreset}>Préparer le mode mains libres posé</button><p class="hint">L’enregistrement de ces réglages ne démarre pas le microphone.</p></section><section><h3>Confort visuel et gestes</h3><label class="check"><input type="checkbox" name="large_controls" bind:checked={draft.large_controls} onchange={edit}/><span>Grandes commandes et texte agrandi dans les blocs, les notes et les réglages</span></label><label class="check"><input type="checkbox" name="reduce_motion" bind:checked={draft.reduce_motion} onchange={edit}/><span>Réduire les animations</span></label><p class="hint">Le petit socle reste discret. Son micro est toujours accessible ; les boutons possèdent un nom et un focus clavier visible.</p></section><section><h3>Écrire dans une autre application</h3><p class="hint">Place le curseur dans le champ où écrire, puis clique le micro ou utilise le raccourci affiché. Aucun choix de destination n’est nécessaire. Écho conserve le champ choisi pendant la prise. Si le champ change ou refuse l’écriture, le résultat reste récupérable dans Écho. Les champs de mots de passe sont exclus.</p><p class="hint">Une commande, un bouton ou un contrôle qui n’est pas un champ texte ne peut pas toujours recevoir une dictée.</p></section><section><h3>Parler à distance</h3><p class="hint">Choisis le microphone dans « Voix et moteur » et regarde son niveau sur le socle pendant une prise. La distance, le bruit et l’écho de la pièce changent la précision. Aucun réglage logiciel ne garantit la reconnaissance d’une voix trop faible.</p><button class="btn" onclick={()=>tab='voice'}>Choisir mon microphone</button></section><section><h3>Lire une autre langue</h3><p class="hint">Dans le + du socle, ajoute Traduire. Sélectionne une zone à l’écran ou colle du texte ; le suivi reste facultatif et peut être arrêté pendant la dictée.</p></section>
{:else if tab==='layout'}<DockDimensions/>{:else if tab==='tutorial'}<Tutorial/>{:else}<h2>Ton espace, ta couleur</h2><p class="intro">Choisis une famille, garde tes favoris et dose la matière. Les notes, la barre vocale, les réglages et les outils de capture suivent immédiatement.</p><MaterialPicker settings={cfg||draft} onChange={appearance}/><section><h3>Retouches récupérables</h3><p class="hint">La dernière capture et ses annotations restent disponibles après fermeture de l’éditeur.</p><button class="btn" onclick={()=>invoke('capture_resume').catch(e=>error=String(e))}><RotateCcw size={15}/>Reprendre la dernière capture</button></section>{/if}
{#if tab!=='layout'}<footer>{#if error}<p class="notice error" role="alert">{error}</p>{/if}<div class="save-row"><span class="status" aria-live="polite">{saving?'Enregistrement…':dirty?'Modifications à enregistrer':message||'Réglages à jour'}</span><button class="btn primary" disabled={saving||!dirty} onclick={save}><Check size={16}/>Enregistrer</button></div></footer>{/if}
</fieldset>{:else}<p class="muted">Chargement des réglages…</p>{#if error}<p class="error">{error}</p>{/if}{/if}</main></div>
<style>
.lexicon{resize:vertical;min-height:120px;line-height:1.6}fieldset{border:0;padding:0;margin:0;min-width:0}
.settings-shell{display:grid;grid-template-columns:220px minmax(0,1fr);height:100vh;overflow:hidden}aside{background:var(--sidebar);padding:28px 16px 16px;display:flex;flex-direction:column;border-right:1px solid var(--border)}.brand{display:flex;align-items:center;gap:8px;font-weight:650;font-size:25px;letter-spacing:-.04em;margin:0 12px 20px}.brand span{font-size:11px;letter-spacing:0;color:var(--muted);font-weight:400}h1{font-size:16px;margin:0 12px 16px}nav{display:grid;gap:3px}nav button{border:0;background:transparent;text-align:left;display:flex;align-items:center;gap:9px;padding:11px 12px;border-radius:7px;font-size:12px;color:var(--muted)}nav button:hover{background:var(--hover)}nav button.chosen{background:var(--accent-soft);color:var(--accent);font-weight:600}.aside-bottom{margin-top:auto}.aside-bottom p{font-size:11px;line-height:1.7;color:var(--muted);margin:16px 12px 0}main{overflow:auto;padding:36px 38px;background:var(--surface)}h2{font-size:22px;margin-bottom:10px}.intro{color:var(--muted);font-size:13px;line-height:1.6;max-width:66ch;margin-bottom:26px}section{padding:20px 0;border-top:1px solid var(--border)}h3{margin-bottom:15px}.label{display:block;font-size:12px;font-weight:600;margin-bottom:15px}.label .field{display:block;margin-top:7px;font-weight:400;font-size:13px}.path{font-size:12px}.actions{display:flex;gap:9px;align-items:center;margin:12px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.grid .label{min-width:0}.hint{color:var(--muted);font-size:12px;line-height:1.6;max-width:66ch}.check{display:flex;gap:10px;align-items:flex-start;font-size:13px;line-height:1.5;margin-bottom:15px}.check input{accent-color:var(--accent);margin-top:4px}dl{font-size:12px;margin:18px 0 0}dl div{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid var(--border)}dt{color:var(--muted)}dd{margin:0}.shortcut{max-width:300px;font-variant-numeric:tabular-nums}footer{margin-top:22px;border-top:1px solid var(--border);padding-top:18px}.save-row{display:flex;justify-content:space-between;align-items:center;gap:15px}@media(max-width:760px){.settings-shell{grid-template-columns:185px minmax(0,1fr)}main{padding:25px 22px}.grid{grid-template-columns:1fr}.actions{flex-wrap:wrap}}
</style>
